def task_func(L, num_dataframes=5, random_seed=None):
    """Generate sampled DataFrames and return their distinct repeated rows.

    Repetition is measured over the concatenated frames, matching the examples;
    the first occurrence and its original concatenation index are retained.
    """
    if not L:
        return pd.DataFrame(), []

    seed(random_seed)
    columns = choices('abcdefghijklmnopqrstuvwxyz', k=len(L[0]))
    df_list = [
