import os
import shutil
import time

# Constants
BACKUP_DIR = '/tmp/backup'


def get_unique_backup_dir():
    """Return an unused timestamp-based path beneath BACKUP_DIR."""
    base = os.path.join(BACKUP_DIR, time.strftime('backup_%Y%m%d%H%M%S'))
    candidate = base
    suffix = 1
    while os.path.lexists(candidate):
        candidate = f'{base}_{suffix}'
        suffix += 1
    return candidate


def task_func(directory):
    """Back up a directory, then remove its contents, collecting errors."""
    backup_directory = get_unique_backup_dir()
    errors = []

    try:
        os.makedirs(BACKUP_DIR, exist_ok=True)
        shutil.copytree(directory, backup_directory, symlinks=True)
    except (OSError, shutil.Error) as exc:
        errors.append(str(exc))
        return backup_directory, errors

    try:
