from random import randint, seed
import pandas as pd


def task_func(goals, penalties, rng_seed=None):
    """Generate match results for five teams, with $1000 per penalty."""
    if goals < 0 or penalties < 0:
        raise ValueError("goals and penalties must be non-negative")

    seed(rng_seed)
    rows = []
    for team in ['Team A', 'Team B', 'Team C', 'Team D', 'Team E']:
        scored = randint(0, goals)
        fine = randint(0, penalties) * 1000
        rows.append([team, f"({scored} goals, ${fine})"])

    return pd.DataFrame(rows, columns=['Team', 'Match Result'])

