import os
import shutil


def task_func(src_folder, backup_dir):
    """Back up the source folder, then delete it after a successful copy."""
    if not os.path.exists(src_folder):
        raise ValueError(f"Source folder does not exist: {src_folder}")

    destination = os.path.join(
        backup_dir, os.path.basename(os.path.normpath(src_folder))
    )
    try:
        shutil.copytree(src_folder, destination)
    except Exception:
        return False

    # Deletion errors must propagate rather than be reported as copy failures.
    shutil.rmtree(src_folder)
    return True

