import random


def task_func(text, seed=None):
    """Generate a password mirroring the ASCII structure of text."""
    if not text:
        raise ValueError("text must not be empty")
    if seed is not None:
        random.seed(seed)

    result = []
    for char in text:
        letter = random.choice(string.ascii_lowercase)
        digit = str(random.randint(0, 9))
        if char in string.ascii_letters:
            result.append(letter)
        elif char in string.digits:
            result.append(digit)
        elif char == ' ':
            result.append(letter if random.random() < 0.5 else digit)
        else:
